(7692139, 1260745, 103142, '<td valign="top">I''m not quite sure what to do with this one. It looks quite cool -- but I''m not sure how you could have used the Brenizer method on it. You need to have a static scene so you can take the multitudinous shots...? Not voting at the moment while I try to wrap my head around it.</td>', 'I''m not quite sure what to do with this one. It looks quite cool -- but I''m not sure how you could have used the Brenizer method on it. You need to have a static scene so you can take the multitudinous shots...? Not voting at the moment while I try to wrap my head around it.', '2021-04-20 11:15:55.000000', NULL, 1),
(7692404, 1260547, 97225, '<td valign="top">Beautiful! My pick for the blue.</td>', 'Beautiful! My pick for the blue.', '2021-04-23 00:57:13.000000', NULL, 1),
